WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_analysis_mixed_material'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '综合资料', 'kp-xingce-data-analysis-mixed-material', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "综合资料综述"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "包含文字、图形、表格两种及以上形式的组合材料。核心是区域打标与互补法则。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "这是国考省考最爱出的压轴大材料，篇幅极长。很多考生一看就心态崩溃。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "快速打标签建立“区域地图”，坚决不读具体数字，利用材料模块间的互补性找数。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[拿到综合长篇材料] --> B[花20秒给区域打标签]\nB --> C[文字区扫首句: 确认它是讲宏观的还是微观的]\nC --> D[图形区看标题: 确认它是走时间轴的(历年)还是分类的]\nD --> E[表格区看表头: 确认它是拆分到地市的还是拆分到产业的]\nE --> F[题目问啥, 就直接空降到对应的隔离区去找, 切忌全篇乱翻]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【场景】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 题目问：2022年第三产业的比重是多少？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "回忆地图：刚才打标时，发现文字区讲的是全国GDP总额，表格区讲的是三大产业的明细。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找部分量（分子）：去表格区找第三产业的具体产值。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找整体量（分母）：去文字区找全国总产值。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "结论：综合资料最爱玩这种“分子分母分居两地”的跨区找数游戏。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "口径不统一：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "图叫“规模以上工业增加值”，表叫“高技术制造业增加值”。跨区取数做除法前，确认两者是否具备真实的包含关系。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "遇到图文表大综合，直接用手或者草稿纸把不需要看的区域物理遮挡住，强行降低视觉处理负担。"}]}]}$$ AS jsonb), NULL, '综合资料的核心读题与防坑技巧。', category_node.id, CAST('["资料分析", "综合资料"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_analysis_mixed_material", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
